      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "春节日程的唯一标识，用于打开日程详情。",
              "sampleValue": "spring-festival-2027"
            },
            "title": {
              "type": "string",
              "description": "春节日程标题。",
              "sampleValue": "春节"
            },
            "dtStart": {
              "type": "string",
