              "sampleValue": "23:59"
            }
          }
        ]
      }
    },
    "view": {
      "timeText": {
        "type": "string",
        "description": "卡片当前时间短文本。",
        "sampleValue": "09:30"
      },
      "dateText": {
        "type": "string",
        "description": "卡片当前日期短文本。",
        "sampleValue": "07/09"
      },
      "countdown": {
        "daysText": {
          "type": "string",
          "description": "距离下一次春节的倒计时天数字符串。",
          "sampleValue": "212天"
        }
      }
    }
  },
  "assetCandidates": []
}

